def clean(df):
    df = df.copy()
    # Normalize island labels (strip stray whitespace so ' Biscoe' -> 'Biscoe')
    df['island'] = df['island'].astype(str).str.strip()
    # Remove the exact duplicate row (52 rows, 51 unique penguin_id)
    df = df.drop_duplicates()
    return df

def answer(df):
    counts = df['island'].value_counts()
    return {island: int(n) for island, n in counts.items()}
